#!/usr/bin/env python3
"""Apply the exact reviewed V5/B1 provider-boundary hardening payload.

This temporary bootstrap refuses to write unless every source preimage is the
reviewed Git blob. It verifies each decompressed output by SHA-256. The
companion workflow removes this file before committing the qualified result.
"""

from __future__ import annotations

import base64
import gzip
import hashlib
import pathlib
import subprocess

ROOT = pathlib.Path(__file__).resolve().parents[1]

PAYLOADS = {
    "codex-rs/hepta-contracts/src/checked_provider_operation.rs": (
        "c128df31054bea193bc38e7d913b7e3d0847b8f2",
        "c79b3e97fa330e461514dcbfb10e1e381e82a349444d8c6c83b7fbc9641f39ae",
        "",
    ),
    "codex-rs/hepta-contracts/src/lib.rs": (
        "ac8b331e60fff8d2882b988f2c39b3e3ed27182d",
        "39e79b540a7c8e2a1a45c51addb032b7992359838aa9a2790488c3a169580035",
        "",
    ),
    "codex-rs/hepta-contracts/tests/provider_verified_use_boundary.rs": (
        "88f0f6ec0e13b606c185af56bd114bd96fea9f6e",
        "665d1491dda5d8167335b829150f398f8f3a7c493c6431dd02e8797c7ba45483",
        "",
    ),
}

FORMAT_PATH = "scripts/verify-hepta-v5-b1-format.py"
FORMAT_PREIMAGE = "d91dc895d1fe38a4493c6c65297207ccf8775a6f"
FORMAT_OLD = '''FILES = (\n    "codex-rs/hepta-contracts/src/checked_provider_operation.rs",\n    "codex-rs/hepta-contracts/tests/provider_verified_use_boundary.rs",\n)'''
FORMAT_NEW = '''FILES = (\n    "codex-rs/hepta-contracts/src/checked_provider_operation.rs",\n    "codex-rs/hepta-contracts/src/lib.rs",\n    "codex-rs/hepta-contracts/tests/provider_verified_use_boundary.rs",\n)'''


def git_blob(path: pathlib.Path) -> str:
    return subprocess.check_output(
        ["git", "hash-object", str(path)], cwd=ROOT, text=True
    ).strip()


def main() -> int:
    for relative, (expected_blob, expected_sha256, payload) in PAYLOADS.items():
        path = ROOT / relative
        observed_blob = git_blob(path)
        if observed_blob != expected_blob:
            raise SystemExit(
                f"refusing {relative}: expected blob {expected_blob}, observed {observed_blob}"
            )
        decoded = gzip.decompress(base64.b64decode(payload, validate=True))
        observed_sha256 = hashlib.sha256(decoded).hexdigest()
        if observed_sha256 != expected_sha256:
            raise SystemExit(
                f"refusing {relative}: payload SHA-256 {observed_sha256} != {expected_sha256}"
            )
        path.write_bytes(decoded)

    format_path = ROOT / FORMAT_PATH
    observed_format_blob = git_blob(format_path)
    if observed_format_blob != FORMAT_PREIMAGE:
        raise SystemExit(
            f"refusing {FORMAT_PATH}: expected blob {FORMAT_PREIMAGE}, observed {observed_format_blob}"
        )
    format_text = format_path.read_text(encoding="utf-8")
    if format_text.count(FORMAT_OLD) != 1:
        raise SystemExit("B1 formatter source preimage is ambiguous")
    format_path.write_text(format_text.replace(FORMAT_OLD, FORMAT_NEW), encoding="utf-8")

    print("PASS_HEPTA_V5_B1_EXACT_BOUNDARY_HARDENING_PAYLOAD")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
